public class OfferUpdateStampConfigStoreTest {
    @Test
    public void keysMatchLegacyAndPerAccountConventions() {
        OfferUpdateStampConfigStore store = new OfferUpdateStampConfigStore();

        assertEquals("geOfferUpdateTimes", store.legacyGlobalKey());
        assertEquals("geOfferUpdateTimes_0", store.perAccountKey(0L));
        assertEquals("geOfferUpdateTimes_12345", store.perAccountKey(12_345L));
    }
}

