import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class OfferPreviewWidgetParserTest {
    @Test
    public void normalizeTextStripsTagsAndPreservesLineBreaks() {
        String normalized = OfferPreviewWidgetParser.normalizeText("<col=ff00ff>Rune</col><br>knife");

        assertEquals("Rune\nknife", normalized);
    }

    @Test
    public void containsAnyDetectsMatchingNeedle() {
        assertTrue(OfferPreviewWidgetParser.containsAny("sell offer", new String[] {"buy offer", "sell offer"}));
        assertFalse(OfferPreviewWidgetParser.containsAny("abc", new String[] {"xyz"}));
    }

    @Test
    public void findItemNameCandidateReturnsNullForMissingInputs() {
        assertNull(OfferPreviewWidgetParser.findItemNameCandidate(null, new String[] {"offer"}, name -> 1));
        assertNull(OfferPreviewWidgetParser.findItemNameCandidate(null, new String[] {"offer"}, null));
    }
}

