package com.osrsfliphub;

import net.runelite.api.GrandExchangeOffer;

final class Stamp {
    int itemId;
    int price;
    int totalQty;
    int filledQty;
    boolean isBuy;
    long spentGp;
    long lastUpdateMs;
    long firstSeenMs;
    long completedMs;
    long lastEmptyMs;

    Stamp() {
    }

    Stamp(int itemId,
                     int price,
                     int totalQty,
                     int filledQty,
                     boolean isBuy,
                     long spentGp,
                     long lastUpdateMs,
                     long firstSeenMs,
                     long completedMs,
                     long lastEmptyMs) {
        this.itemId = itemId;
        this.price = price;
        this.totalQty = totalQty;
        this.filledQty = filledQty;
        this.isBuy = isBuy;
        this.spentGp = spentGp;
        this.lastUpdateMs = lastUpdateMs;
        this.firstSeenMs = firstSeenMs;
        this.completedMs = completedMs;
        this.lastEmptyMs = lastEmptyMs;
    }

    /**
     * Independent copy. Stamps are mutated in place by the tracking rules, so a
     * caller that needs the pre-update fill level must copy before tracking.
     */
    static Stamp copyOf(Stamp stamp) {
        if (stamp == null) {
            return null;
        }
        return new Stamp(
            stamp.itemId,
            stamp.price,
            stamp.totalQty,
            stamp.filledQty,
            stamp.isBuy,
            stamp.spentGp,
            stamp.lastUpdateMs,
            stamp.firstSeenMs,
            stamp.completedMs,
            stamp.lastEmptyMs
        );
    }

    static Stamp fromSnapshot(OfferSnapshot snapshot, long timestamp) {
        if (snapshot == null) {
            return null;
        }
        long safeTimestamp = timestamp > 0 ? timestamp : System.currentTimeMillis();
        return new Stamp(
            snapshot.itemId,
            snapshot.price,
            snapshot.totalQty,
            snapshot.filledQty,
            snapshot.isBuy,
            snapshot.spentGp,
            safeTimestamp,
            safeTimestamp,
            0L,
            0L
        );
    }

    static Stamp fromOffer(GrandExchangeOffer offer, long timestamp, boolean isBuy) {
        if (offer == null) {
            return null;
        }
        long safeTimestamp = timestamp > 0 ? timestamp : System.currentTimeMillis();
        return new Stamp(
            offer.getItemId(),
            offer.getPrice(),
            offer.getTotalQuantity(),
            offer.getQuantitySold(),
            isBuy,
            offer.getSpent(),
            safeTimestamp,
            safeTimestamp,
            0L,
            0L
        );
    }
}

