package com.osrsfliphub;

import java.util.List;
import javax.swing.*;

final class ItemsRender {
    @FunctionalInterface
    interface RefreshTextBuilder {
        String build(long asOfMs, Long priceCacheMs);
    }

    void renderItems(JPanel listPanel,
                     AgeTooltip ageTooltipCoordinator,
                     ItemListContentRenderer itemListContentRenderer,
                     FlipHubItem offerPreviewItem,
                     long offerAsOfMs,
                     List<FlipHubItem> lastItems,
                     long lastAsOfMs,
                     boolean showBookmarkedOnly,
                     String searchQuery,
                     JLabel refreshLabel,
                     Long lastPriceCacheMs,
                     Long offerPriceCacheMs,
                     RefreshTextBuilder refreshTextBuilder,
                     JPanel footerPanel,
                     JScrollPane scrollPane) {
        if (listPanel == null || ageTooltipCoordinator == null || itemListContentRenderer == null) {
            return;
        }

        // The renderer answers whether it had to rebuild the panel or could write the new
        // values into the rows already in it. A refresh that only moved the numbers has no
        // layout to run and no hover to put back - that is the whole point of asking.
        boolean rebuilt = itemListContentRenderer.renderList(
            listPanel,
            offerPreviewItem,
            offerAsOfMs,
            lastItems,
            lastAsOfMs,
            showBookmarkedOnly,
            searchQuery
        );

        long refreshAsOf = lastAsOfMs > 0 ? lastAsOfMs : offerAsOfMs;
        Long refreshCacheMs = lastPriceCacheMs != null ? lastPriceCacheMs : offerPriceCacheMs;
        if (refreshAsOf > 0 && refreshLabel != null && refreshTextBuilder != null) {
            refreshLabel.setText(refreshTextBuilder.build(refreshAsOf, refreshCacheMs));
        }
        if (footerPanel != null) {
            footerPanel.setVisible(offerPreviewItem == null);
        }

        if (offerPreviewItem != null && scrollPane != null) {
            JScrollBar bar = scrollPane.getVerticalScrollBar();
            if (bar != null) {
                bar.setValue(0);
            }
        }

        if (rebuilt) {
            listPanel.revalidate();
            listPanel.repaint();
            // The rows the pointer was over are gone, replaced by rows that never heard of it.
            HoverRestorer.restoreAfterRebuild(listPanel);
        }
        ageTooltipCoordinator.ensureCountdownTimer();
    }
}

