package com.osrsfliphub;

import javax.swing.*;

final class FlipHubSearchCoordinator {
    private Timer searchTimer;

    void hookSearchListener(JTextField field, Runnable onSearchTriggered) {
        if (field == null || onSearchTriggered == null) {
            return;
        }
        installDocumentListener(field, () -> scheduleSearch(onSearchTriggered));
    }

    private void installDocumentListener(JTextField field, Runnable onChange) {
        field.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            @Override
            public void insertUpdate(javax.swing.event.DocumentEvent e) {
                onChange.run();
            }

            @Override
            public void removeUpdate(javax.swing.event.DocumentEvent e) {
                onChange.run();
            }

            @Override
            public void changedUpdate(javax.swing.event.DocumentEvent e) {
                onChange.run();
            }
        });
    }

    private void scheduleSearch(Runnable onSearchTriggered) {
        if (searchTimer == null) {
            searchTimer = new Timer(300, e -> onSearchTriggered.run());
            searchTimer.setRepeats(false);
        }
        searchTimer.restart();
    }
}

