package com.osrsfliphub;

/**
 * Transitional bridge giving migrated {@code @Inject} services a lazy, call-time
 * handle to collaborators that are still built by the hand-rolled lifecycle
 * orchestrators. Preserves the original lazy-supplier semantics during the
 * incremental migration. Removed once the orchestrators are collapsed and every
 * service is injected directly.
 */
final class Access {
    private static volatile GeLifecyclePlugin plugin;

    private Access() {
    }

    static void set(GeLifecyclePlugin value) {
        plugin = value;
    }

    static GeLifecyclePlugin plugin() {
        GeLifecyclePlugin active = plugin;
        if (active == null) {
            throw new IllegalStateException("Plugin not initialized");
        }
        return active;
    }

    static GeLifecyclePlugin pluginOrNull() {
        return plugin;
    }

    /**
     * Whether there is a logged-in character behind this client.
     *
     * <p>One place, because a dozen callers ask it and each one that spelled it out was another
     * chance to forget that the client reference itself can be null before start-up finishes.
     */
    static boolean loggedIn(net.runelite.api.Client client) {
        return client != null && client.getGameState() == net.runelite.api.GameState.LOGGED_IN;
    }
}

