package com.osrsfliphub;

import javax.inject.*;

@Singleton
final class TradeDeltaRecorder {
    private final long accountwideKey = Const.ACCOUNTWIDE_KEY;

    @Inject
    TradeDeltaRecorder() {
    }

    private void ensureLocalSessionStart(long accountKey, long tsClientMs) {
        TradeSession service = Bridge.get(TradeSession.class);
        if (service != null) {
            service.ensureLocalSessionStart(accountKey, tsClientMs);
        }
    }

    private void applyDeltaToStatsCache(long accountKey, Delta delta) {
        LocalStatsCacheService service = Bridge.get(LocalStatsCacheService.class);
        if (service != null) {
            service.applyDelta(accountKey, delta);
        }
    }

    private void rebuildStatsCache(long accountKey) {
        LocalStatsCacheService service = Bridge.get(LocalStatsCacheService.class);
        if (service != null) {
            service.rebuildFromStored(accountKey);
        }
    }

    /**
     * @param offerStartMs when the offer this event belongs to was placed, from the slot's
     *                     stamp; zero when the slot has no stamp any more, as after a collect
     */
    boolean record(GeEvent event, boolean baselineSynthetic, long offerStartMs) {
        if (event == null) {
            return false;
        }

        boolean hasDelta = event.delta_qty > 0 || event.delta_gp > 0;
        if (!hasDelta && !"OFFER_COMPLETED".equals(event.event_type)) {
            return false;
        }
        if (baselineSynthetic) {
            return false;
        }

        AccountSession sessionService = Bridge.get(AccountSession.class);
        long accountKey = sessionService != null ? sessionService.resolveLocalAccountKey() : 0L;
        if (accountKey <= 0) {
            return false;
        }

        LocalTradesRuntime tradesRuntime = Access.plugin().getLocalTradesRuntimeService();
        tradesRuntime.ensureProfileLoaded(accountKey);
        tradesRuntime.ensureProfileLoaded(accountwideKey);
        ensureLocalSessionStart(accountKey, event.ts_client_ms);
        ensureLocalSessionStart(accountwideKey, event.ts_client_ms);

        Delta delta = new Delta(
            event.ts_client_ms,
            event.slot,
            event.item_id,
            event.is_buy,
            event.delta_qty,
            event.delta_gp,
            event.event_type,
            event.price,
            baselineSynthetic,
            Math.max(0L, offerStartMs),
            0L
        );

        ItemLookup itemLookup = Bridge.get(ItemLookup.class);
        if (itemLookup != null) {
            itemLookup.cacheItemName(event.item_id);
        }
        // Read before the delta lands, so the rank check below can see what this sale changed.
        long profitBefore = RankUp.lifetimeProfit(accountKey);
        TradeOfferCollapser.Outcome outcome = tradesRuntime.appendTradeDeltaPair(accountKey, accountwideKey, delta);
        if (outcome == TradeOfferCollapser.Outcome.DROPPED) {
            // Nothing stored, so nothing may reach the aggregate either: a repeat counted
            // live but absent from disk is exactly the running-versus-restart drift.
            return false;
        }
        if (outcome == TradeOfferCollapser.Outcome.COLLAPSED) {
            // The offer's fills were already applied one by one as they arrived, and the
            // stored list now holds one record in their place. Replaying it is what a
            // fresh start will do, so it is done now: the numbers never depend on whether
            // the client has restarted since the offer completed.
            rebuildStatsCache(accountKey);
            if (accountwideKey != accountKey) {
                rebuildStatsCache(accountwideKey);
            }
        } else {
            applyDeltaToStatsCache(accountKey, delta);
            if (accountwideKey != accountKey) {
                applyDeltaToStatsCache(accountwideKey, delta);
            }
        }
        // Every live sale passes through here and nothing else does, which is what keeps
        // imports, recorded recipes and wipes from setting off a rank-up.
        RankUp rankUp = Bridge.get(RankUp.class);
        if (rankUp != null) {
            rankUp.onSale(profitBefore, RankUp.lifetimeProfit(accountKey));
        }
        tradesRuntime.persistLocalTrades(accountKey);
        // The accountwide file is not written here. Its stored deltas are never read: the
        // accountwide ledger is rebuilt by merging the per-profile files, which the line above
        // keeps current. Writing it too doubled the disk work on every fill for nothing.
        PanelRefresh coordinator = Access.plugin().getPanelRefreshCoordinator();
        if (coordinator != null) {
            coordinator.triggerStatsRefresh(Access.plugin().scheduler);
            coordinator.triggerPanelRefresh(Access.plugin().scheduler);
        }
        return true;
    }
}

