package com.osrsfliphub;

import java.util.*;
import javax.inject.*;
import net.runelite.api.Client;

@Singleton
final class AccountSession {
    private final Client client;
    private long lastMergedAccountHash = -1L;
    private long lastMergedNameKey = -1L;

    @Inject
    AccountSession(Client client) {
        this.client = client;
    }

    private boolean isLoggedIn() {
        return Access.loggedIn(client);
    }

    long resolveLocalAccountKey() {
        if (!isLoggedIn()) {
            return -1L;
        }
        long accountHash = resolveAccountHash();
        long nameKey = resolveNameAccountKey();
        maybeMergeLocalAccounts(accountHash, nameKey);
        if (accountHash > 0) {
            return accountHash;
        }
        if (nameKey > 0) {
            return nameKey;
        }
        return -1L;
    }

    long resolveLimitAccountKey(long fallbackAccountKey) {
        if (fallbackAccountKey > 0) {
            return fallbackAccountKey;
        }
        long localAccountKey = resolveLocalAccountKey();
        if (localAccountKey > 0) {
            return localAccountKey;
        }
        return fallbackAccountKey;
    }

    long resolveAccountHash() {
        if (!isLoggedIn()) {
            return -1L;
        }
        try {
            long hash = client != null ? client.getAccountHash() : -1L;
            return hash > 0 ? hash : -1L;
        } catch (RuntimeException ignored) {
            return -1L;
        }
    }

    String resolveDisplayName() {
        try {
            String name = client != null && client.getLocalPlayer() != null
                ? client.getLocalPlayer().getName() : null;
            return name != null ? name.trim() : null;
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    void updateLocalAccountSessionStart(Map<Long, Long> localSessionStartByAccount,
                                        Object localStatsLock,
                                        long accountwideKey) {
        if (localSessionStartByAccount == null || localStatsLock == null) {
            return;
        }
        long accountKey = resolveAccountHash();
        if (accountKey <= 0) {
            return;
        }
        startSessionIfAbsent(localSessionStartByAccount, localStatsLock, accountKey, accountwideKey,
            System.currentTimeMillis());
    }

    void startSessionIfAbsent(Map<Long, Long> localSessionStartByAccount,
                              Object localStatsLock,
                              long accountKey,
                              long accountwideKey,
                              long nowMs) {
        if (localSessionStartByAccount == null || localStatsLock == null || accountKey <= 0) {
            return;
        }
        synchronized (localStatsLock) {
            // Only the first login of a session starts the clock. The client reports
            // LOGGED_IN again after every world hop and every loading screen, and
            // overwriting here would restart the Session range each time, emptying it
            // while the session timer beside it kept counting.
            localSessionStartByAccount.putIfAbsent(accountKey, nowMs);
            if (accountwideKey >= 0) {
                localSessionStartByAccount.putIfAbsent(accountwideKey, nowMs);
            }
        }
    }

    /** Ends the session: the next login starts a new one. */
    void clearLocalAccountSessionStarts(Map<Long, Long> localSessionStartByAccount, Object localStatsLock) {
        if (localSessionStartByAccount == null || localStatsLock == null) {
            return;
        }
        synchronized (localStatsLock) {
            localSessionStartByAccount.clear();
        }
    }

    void ensureLocalSessionStart(Map<Long, Long> localSessionStartByAccount,
                                 Object localStatsLock,
                                 long accountKey,
                                 long nowMs) {
        if (localSessionStartByAccount == null || localStatsLock == null) {
            return;
        }
        synchronized (localStatsLock) {
            localSessionStartByAccount.putIfAbsent(accountKey, nowMs);
        }
    }

    long resolveStatsSessionStartMs(Map<Long, Long> localSessionStartByAccount,
                                    Object localStatsLock,
                                    long accountKey,
                                    long nowMs) {
        if (accountKey < 0) {
            return nowMs;
        }
        if (localSessionStartByAccount == null || localStatsLock == null) {
            return nowMs;
        }
        long sessionStartMs = nowMs;
        synchronized (localStatsLock) {
            Long storedStart = localSessionStartByAccount.get(accountKey);
            if (storedStart != null && storedStart > 0) {
                sessionStartMs = storedStart;
            } else {
                localSessionStartByAccount.put(accountKey, nowMs);
            }
        }
        return sessionStartMs;
    }

    private long resolveNameAccountKey() {
        String name = resolveDisplayName();
        if (name == null) {
            return -1L;
        }
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return -1L;
        }
        long fallback = trimmed.toLowerCase(Locale.US).hashCode();
        return fallback != 0 ? Math.abs(fallback) : 1L;
    }

    private void maybeMergeLocalAccounts(long accountHash, long nameKey) {
        if (accountHash <= 0 || nameKey <= 0 || accountHash == nameKey) {
            return;
        }
        if (accountHash == lastMergedAccountHash && nameKey == lastMergedNameKey) {
            return;
        }
        // Folding the two together is housekeeping, not part of the answer. Asked before the
        // plugin has finished starting there is nothing to fold with, and throwing here would
        // take down whatever only wanted to know which account it was talking about.
        GeLifecyclePlugin plugin = Access.pluginOrNull();
        if (plugin == null) {
            return;
        }
        plugin.getProfileWorkflowService().mergeLocalAccountData(accountHash, nameKey);
        lastMergedAccountHash = accountHash;
        lastMergedNameKey = nameKey;
    }
}

