package com.osrsfliphub;

final class ProfileHashFileParser {
    private static final String HASH_PREFIX = "hash_";
    private static final String JSON_SUFFIX = ".json";

    private ProfileHashFileParser() {
    }

    static Long parsePositiveHashFromProfileFileName(String fileName) {
        if (fileName == null
            || !fileName.startsWith(HASH_PREFIX)
            || !fileName.endsWith(JSON_SUFFIX)) {
            return null;
        }

        String hashPart = fileName.substring(HASH_PREFIX.length(), fileName.length() - JSON_SUFFIX.length());
        if (hashPart.isEmpty()) {
            return null;
        }

        try {
            long hash = Long.parseLong(hashPart);
            return hash > 0 ? hash : null;
        } catch (NumberFormatException ignored) {
            return null;
        }
    }
}

