@javax.inject.Singleton
final class WidgetRead {
    private static final int WIDGET_GROUP_SIZE = 6;

    @javax.inject.Inject
    WidgetRead() {
    }

    boolean hasCompleteWidgetGroups(Widget[] historyWidgets) {
        int widgetCount = historyWidgets != null ? historyWidgets.length : 0;
        return widgetCount > 0 && (widgetCount % WIDGET_GROUP_SIZE) == 0;
    }

    List<Trade> parseTrades(Widget[] historyWidgets) {
        return WidgetParser.parse(historyWidgets);
    }

    List<Trade> tryParseReadyTrades(Widget[] historyWidgets) {
        if (!hasCompleteWidgetGroups(historyWidgets)) {
            return null;
        }
        return parseTrades(historyWidgets);
    }
}

