import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
final class Trade {
    final int itemId;
    final boolean isBuy;
    final int quantity;
    final int price;
    final long totalGp;

    boolean isValid() {
        return itemId > 0
            && quantity > 0
            && price > 0
            && totalGp > 0L;
    }
}

